commit d6dd218da2f8dd56ad7a563d9924222fd9770443
Author: Yufen Yu <yuyufen@huawei.com>
Date:   Sat Jun 19 15:50:05 2021 +0800

    block: call bdput() to avoid memleak

    hulk inclusion

    -------------------------------------------------

    bdget_disk() will get bd_inode, so it need to do bdput().

    Signed-off-by: Yufen Yu <yuyufen@huawei.com>
    Reviewed-by: Hou Tao <houtao1@huawei.com>
    Signed-off-by: Yang Yingliang <yangyingliang@huawei.com>

diff --git a/block/genhd.c b/block/genhd.c
index b5820cf94b5d2..a906426b5f4fd 100644
--- a/block/genhd.c
+++ b/block/genhd.c
@@ -783,8 +783,10 @@ void del_gendisk(struct gendisk *disk)
 		delete_partition(disk, part->partno);
 	}
 	disk_part_iter_exit(&piter);
-	if (bdev)
+	if (bdev) {
 		mutex_unlock(&bdev->bd_mutex);
+		bdput(bdev);
+	}

 	invalidate_partition(disk, 0);
 	bdev_unhash_inode(disk_devt(disk));

